        Phrase("Ils n'ont pas payé", "They didn't pay", "Hawakulipa", null, "Negation wraps the AUXILIARY: n'ont pas.", "Je n'ai pas mangé. The pas goes after avoir/être, before the participle.", "A2"),
        Phrase("As-tu déjà voté ?", "Have you ever voted?", "Ushawahi kupiga kura?", null, "déjà + passé composé = ever/yet.", "As-tu déjà…? / Je n'ai jamais… — the already/never pair examiners love.", "B1"),
        Phrase("Elle s'est levée tard", "She woke up late", "Aliamka kuchelewa", null, "Reflexives: être + agreement (she → -e).", "Reflexive verbs always take être: je me suis lavé(e). Agreement with subject, mostly.", "B1"),
        Phrase("Les mangues que j'ai mangées", "The mangoes I ate", "Maembe niliyokula", null, "que + preceding direct object → agreement.", "B1 trap: agreement with a PRECEDING object: les lettres que j'ai écrites. No object before → no agreement.", "B1"),
