        Phrase("Il faisait beau", "The weather was nice", "Hali ya hewa ilikuwa nzuri", null, "Weather in imparfait: background description.", "Background (imparfait) vs event (passé composé): Il faisait beau quand je suis sorti.", "B1"),
        Phrase("Je lisais pendant le cours", "I was reading during class", "Nilikuwa ninasoma darasani", null, "Ongoing action interrupted by an event.", "Je lisais QUAND le prof est entré. Interruption formula — exam gold.", "B1"),
