    Lesson("g-pronoms", "🔗", "Pronoms COD/COI, y, en", "Object pronouns & shortcuts", "Viwakilishi", listOf(
        Phrase("Je le vois", "I see him/it", "Ninamwona", "Namwona", "le/la BEFORE the verb. French word order flips English.", "COD pronouns (me, te, le/la, nous, vous, les) go before the verb: Je le mange. Je les aime.", "B1", true),
        Phrase("Elle m'appelle", "She's calling me", "Ananipigia", "Ananipigia", "m' before vowel: me → m'.", "me/te/se shorten before vowels: m'appelle, t'aime, s'habille. Sound rule, automatic.", "B1"),
        Phrase("Je lui parle", "I'm talking to him/her", "Ninaongea naye", "Naongea naye", "lui = to him OR to her (COI).", "parler À quelqu'un → lui. Je lui donne, je lui écris. Gender invisible — context decides.", "B1"),
        Phrase("Donne-le-moi", "Give it to me", "Nipe", "Nipe", "Commands flip: pronouns AFTER, hyphenated.", "Affirmative orders: Dis-moi ! Regarde-les ! Negative keeps order: Ne me regarde pas !", "B1"),
        Phrase("J'y vais", "I'm going there", "Ninaenda huko", "Naenda huko", "y = there / à + place.", "y replaces à + place: J'y pense (penser à), je m'y habitue. Tiny word, huge frequency.", "B1"),
        Phrase("J'en veux deux", "I want two (of them)", "Nataka mbili", "Nataka mbili", "en = of it/them, quantities.", "en for numbers and partitives: J'en ai trois. Tu en veux ? // J'en parle (parler de).", "B1"),
        Phrase("Ne t'inquiète pas", "Don't worry", "Usijali", "Usijali", "Reflexive order: ne + te + verb + pas.", "Reflexives in orders: Assieds-toi ! vs Ne t'assieds pas ! The toi/te switch is the trap.", "A2"),
        Phrase("Je m'en souviens", "I remember it", "Ninakumbuka", null, "se souvenir DE → en. Fixed combo.", "se souvenir de → s'en souvenir. se moquer de → s'en moquer. Learn verb + preposition together.", "B2"),
        Phrase("Il faut s'y mettre", "You have to get down to it", "Lazima uanze sasa", null, "s'y mettre: reflexive + y. Exam-essay ready.", "Il faut s'y mettre sérieusement — perfect B2 conclusion-line energy for compositions.", "B2"),
        Phrase("Je les ai déjà lus", "I've already read them", "Nimeshazisoma", null, "COD before auxiliary → agreement: lus (m pl).", "Same rule as g-passe lesson: preceding object agrees. les mangues → mangées, les livres → lus.", "B1"),
        Phrase("Écoute-moi bien", "Listen to me well", "Nisikilize vizuri", "Nisikize vizuri", "Affirmative order: pronoun AFTER.", "Écoute-moi, Regarde-nous, Dis-leur. Hyphens, accent on the order.", "B1"),
