// ─── UNIT 8 · LYCÉE / KCSE (u8) ─────────────────────────────────────────────
// Kenyan high-school French: three papers — Paper 1 listening, Paper 2
// reading + grammar + composition, Paper 3 oral. No exact mark schemes
// claimed here; skills and formats only, so nothing goes stale.

    Lesson("k-examen", "📋", "Format de l'examen", "KCSE format & strategy", "Muundo wa mtihani", listOf(
        Phrase("L'épreuve dure deux heures", "The paper lasts two hours", "Mtihani unachukua masaa mawili", null, "Plan your time per section before writing a word.", "Lisez tout le sujet d'abord. Allocate: comprehension 30 min, grammar 25, composition 45. Watch the clock.", "A2", true),
        Phrase("Lis les questions d'abord", "Read the questions first", "Soma maswali kwanza", "Soma maswali kwanza", "Questions tell you what to hunt for.", "For listening AND reading: questions first, then the text. Underline key words (qui, quand, combien).", "A2"),
        Phrase("Ne laisse aucune case vide", "Never leave a blank", "Usiachie jibu wazi", "Usiachie blank", "A guess can earn method marks; a blank earns zero.", "Even unsure: write the closest answer in full French sentences where asked. Blanc = 0 garanti.", "A2"),
        Phrase("Recopie sans fautes", "Copy out without errors", "Nakili bila makosa", null, "Dictation: accents count, agreements count.", "Dictée strategy: listen for liaisons (les‿amis), silent letters (parlent vs parle), verb endings.", "A2"),
        Phrase("Justifie avec le texte", "Justify from the text", "Thibitisha kwa kifungu", null, "'Vrai ou faux ? Justifiez' needs the exact line.", "Quote 5–8 words from the passage as proof. Wrong justification = half marks lost.", "B1"),
        Phrase("Écris lisiblement", "Write legibly", "Andika vizuri", null, "Examiners can't mark what they can't read.", "Leave a line between answers, cross out cleanly with ONE line. Presentation is free marks.", "A1"),
        Phrase("Vérifie les accords à la fin", "Check agreements at the end", "Angalia makubaliano mwishoni", null, "Keep 5 minutes for re-reading.", "Final sweep: every adjective matches, every passé composé agrees, every verb matches its subject.", "B1"),
        Phrase("Bon courage pour demain", "Good luck for tomorrow", "Kila la heri kesho", "Good luck kesho", "Say it to classmates — examiners like confident candidates.", "Le jour J: arrive early, ID ready, breathe. Stress eats accents first.", "A1"),
        Phrase("J'ai révisé toute la semaine", "I revised all week", "Nimesoma wiki nzima", "Nimesoma wiki mzima", "tout + time = the whole time.", "toute la semaine, tout le mois, tous les jours. Agreement: tout/tous/toute/toutes.", "A2"),
        Phrase("Je suis prêt pour l'oral", "I'm ready for the oral", "Niko tayari kwa mtihani wa kuzungumza", "Niko ready kwa oral", "prêt + pour + noun.", "prêt à + infinitive: prêt à répondre. prêt pour + noun: prêt pour l'examen.", "B1"),
        Phrase("J'apporte deux stylos bleus", "I bring two blue pens", "Ninaleta kalamu mbili za buluu", null, "Pack the kit the night before.", "stylos bleus: adjective agrees (masc pl). Kit: 2 stylos, crayon, gomme, règle, ID.", "A1"),
        Phrase("Élimine les mauvaises réponses", "Eliminate wrong answers", "Ondoa majibu mabaya", null, "Multiple choice: cross out 2, choose between 2.", "QCM method: eliminate absolutes (toujours, jamais) first, then re-read the stem.", "A2"),
        Phrase("Garde dix minutes pour relire", "Keep ten minutes to re-read", "Weka dakika kumi kusoma tena", null, "Plan time backwards from the bell.", "Budget: comprehension 35, grammar 25, composition 50, re-read 10. Write the plan on the margin.", "A2"),
        Phrase("Respire avant de commencer", "Breathe before starting", "Pumua kabla ya kuanza", null, "3 slow breaths beat 3 rushed minutes.", "Stress eats accents first. Calm start = clean copy. 3-3-3 breathing: in, hold, out.", "A1"),
        Phrase("Souligne les mots-clés", "Underline key words", "Pigia mstari maneno muhimu", null, "Qui, quand, combien, où — ink them.", "Keywords anchor answers: circle them in the question AND the text. Same word both sides = proof.", "A2"),
        Phrase("La veille, dors huit heures", "The night before, sleep eight hours", "Usiku kabla, lala masaa nane", "Usiku kabla, lala eight hours", "Sleep consolidates; cramming dissolves.", "Dormir → dormi (avoir, no agreement). Stop at 9pm: fiches away, sleep, win.", "A2")
    ), "u8", culture = "KCSE French rewards method as much as knowledge: read questions first, justify from the text, never leave blanks, and save five minutes to check every agreement."),
    Lesson("k-lettre", "✉️", "La lettre", "Formal & friendly letters", "Barua", listOf(
        Phrase("Nairobi, le 12 mai 2026", "Nairobi, 12 May 2026", "Nairobi, 12 Mei 2026", null, "Place + date top right. Always.", "En-tête: town, comma, le + date. Nairobi, le 3 mars 2026. No shortcuts.", "A2", true),
        Phrase("Monsieur le Proviseur", "Dear Principal (m)", "Mheshimiwa Mkuu", null, "Formal titles: Monsieur le / Madame la + role.", "Monsieur le Directeur, Madame la Professeure. Never 'Cher Monsieur' to officials.", "B1"),
        Phrase("Je me permets de vous écrire", "I take the liberty of writing", "Ninajiruhusu kuwaandikia", null, "The formal-letter opener. Memorize exactly.", "Je me permets de vous écrire au sujet de… = the KCSE formal letter key. Opens every official letter.", "B1"),
