        Phrase("Veuillez agréer mes salutations", "Please accept my regards", "Tafadhali pokea salamu zangu", null, "The formal sign-off. Full version adds 'distinguées'.", "Veuillez agréer, Monsieur, l'expression de mes salutations distinguées. Copy it perfectly.", "B1"),
        Phrase("Mon cher Achieng", "My dear Achieng", "Mpenzi Achieng", null, "Friendly letters open warmly: Mon cher / Ma chère.", "Amicale structure: greeting + news + questions + promise to write + Bises / Amitiés.", "A2"),
        Phrase("Donne-moi de tes nouvelles", "Send me your news", "Niambie habari zako", "Niupdate na stories", "Friendly-letter must-have line.", "Donne-moi de tes nouvelles + Réponds-moi vite ! Examiners check for interaction, not just narration.", "A2"),
        Phrase("Ci-joint mon certificat", "Enclosed is my certificate", "Nimeambatanisha cheti changu", null, "Applications: mention enclosures.", "Ci-joint… / Vous trouverez ci-joint… Then list: mon CV, mes relevés de notes.", "B1"),
        Phrase("Je vous remercie d'avance", "Thank you in advance", "Nawashukuru mapema", null, "Polite pressure, formal register.", "remercier DE: Je vous remercie de votre attention. Preposition de is the tested point.", "B1"),
        Phrase("Expéditeur en haut à gauche", "Sender top-left", "Mtumaji juu kushoto", null, "Your address first, then theirs.", "En-tête order: expéditeur (you) top-left, destinataire right, lieu + date right. Format marks.", "A2"),
