        Phrase("C'est pourquoi je propose", "That is why I propose", "Ndiyo maana napendekeza", null, "c'est pourquoi = conclusion pivot.", "c'est pourquoi / c'est ainsi que: pivot from argument to proposal. Conclusion engine.", "B1"),
        Phrase("En outre, les jeunes souffrent", "Besides, the youth suffer", "Aidha, vijana wanateseka", null, "en outre = formal addition.", "en outre, de surcroît: formal de plus. Vary connectors — repetition caps marks.", "B1"),
        Phrase("En somme, agissons vite", "In short, let's act fast", "Kwa ufupi, tuchukue hatua haraka", null, "en somme + imperative call.", "Final line formula: en somme + present + imperative. Leave the examiner with motion.", "B1"),
        Phrase("Et si on changeait tout ?", "What if we changed everything?", "Na tukibadilisha kila kitu?", null, "Rhetorical question hooks readers.", "Hook options: question, chiffre choc (80%…), citation. Never start « Le sujet que… ».", "B1")
