    Lesson("k-comprehension", "🔍", "Compréhension", "Reading strategies", "Ufahamu", listOf(
        Phrase("De quoi parle le texte ?", "What is the text about?", "Kifungu kinahusu nini?", "Story ni kuhusu nini?", "First question first: theme in one line.", "Skim for the thème: title + first + last paragraph. Answer in YOUR words, not copied.", "A2", true),
        Phrase("Relevez deux détails", "Pick out two details", "Taja maelezo mawili", null, "relever = lift from the text, exactly.", "Relevez/citez = copy word-for-word with quotes. Trouvez = you may reformulate. Different verbs, different moves.", "B1"),
        Phrase("D'après le troisième paragraphe", "According to the third paragraph", "Kulingana na aya ya tatu", null, "Stay INSIDE the cited paragraph.", "The paragraph number is a fence: answers outside it score zero even if true.", "A2"),
        Phrase("L'auteur dénonce la corruption", "The author denounces corruption", "Mwandishi anakemea ufisadi", null, "dénoncer/critiquer/souligner: opinion verbs.", "Tone questions: dénonce (attacks), salue (praises), regrette, propose. One verb = the author's stance.", "B1"),
