        Phrase("Quel titre donneriez-vous ?", "What title would you give?", "Ungetoa kichwa gani?", null, "Title = theme + tone, under 6 words.", "A good titre: noun phrase, no verb, no copying the original title. 'Solidarité villageoise' beats sentences.", "B1"),
        Phrase("Lisez entre les lignes", "Read between the lines", "Soma kati ya mistari", "Soma between lines", "Implicite questions test inference.", "Explicite = in the text. Implicite = must infer: tone, intention, unstated cause. Signal the reasoning.", "B1"),
