    Lesson("k-pieges", "🪤", "Pièges classiques", "Classic exam traps", "Mitego ya mtihani", listOf(
        Phrase("Je suis allé, pas j'ai allé", "Allé with être, never avoir", "Tumia 'suis', si 'ai'", null, "aller/venir/partir = être. Always.", "DR MRS VANDERTRAMP list: Devenir, Revenir, Mourir, Retourner, Sortir, Venir, Arriver, Naître, Descendre, Entrer, Rester, Tomber, Rentrer, Aller, Monter, Partir.", "A2", true),
