        Phrase("Les filles que j'ai vues", "The girls I saw", "Wasichana niliowaona", null, "Preceding object → agreement: vues.", "les + feminine plural before auxiliary: vues. Compare: J'ai vu les filles (nothing before, no agreement).", "B1"),
