        Phrase("Tout le monde est venu", "Everyone came (SINGULAR)", "Kila mtu amekuja", null, "tout le monde + singular verb.", "Collectives stay singular: tout le monde est, la plupart ont (exception!). la foule applaudit.", "B1"),
