// ─── U7 SUPPLEMENT · THE 9 PARTS OF SPEECH IN DEPTH ─────────────────────────
// U7 already covers articles, adjectives, verbs and pronouns in dedicated
// lessons; these five complete the set: nouns, adverbs, prepositions,
// conjunctions, interjections.

    Lesson("g-noms", "📦", "Noms en profondeur", "Nouns: gender & number rules", "Nomino kwa undani", listOf(
        Phrase("Le voyage et la valise", "The journey (m) and the suitcase (f)", "Safari na sutikesi", null, "-age masculine, suitcase feminine: memorize pairs.", "Endings that predict gender: -age/-ment/-isme/-oir → masculine; -tion/-sion/-té/-ette/-elle → feminine. ~80% reliable.", "A2", true),
        Phrase("Un oiseau, des oiseaux", "A bird, birds", "Ndege, ndege", null, "-au → -aux in plural. Silent x.", "Seven -ou nouns take -x: bijou, caillou, chou, genou, hibou, joujou, pou. Mnemonic: the jewel-pebble-cabbage gang.", "B1"),
        Phrase("Un journal, des journaux", "A newspaper, newspapers", "Gazeti, magazeti", null, "-al → -aux. Classic spelling rule.", "-al → -aux: journal/journaux, cheval/chevaux, animal/animaux. Exceptions: bal/bals, carnaval/carnavals, festival/festivals.", "B1"),
        Phrase("Les yeux de ma mère", "My mother's eyes", "Macho ya mama yangu", null, "œil → yeux. Totally irregular, very common.", "Body irregulars: œil/yeux, ciel/cieux. Aïe ! J'ai mal aux yeux après la révision.", "A2"),
        Phrase("Un porte-monnaie vide", "An empty wallet", "Pochi tupu", "Wallet tupu", "Compound nouns: porte- + noun stays invariable.", "porte-, couvre-, garde- compounds: un porte-monnaie, des porte-monnaie (no s). But: des grands-mères (both agree). Two systems — check the verb inside.", "B1"),
        Phrase("La plupart des élèves", "Most students", "Wanafunzi wengi", null, "la plupart + PLURAL verb (exception!).", "la plupart ont réussi, la plupart des filles sont venues. Rare plural-collective — examiners test it yearly.", "B1"),
        Phrase("Un amour d'enfant", "A lovely child (lit: a love of a child)", "Mtoto mpendez unayempenda", null, "amour is masculine singular, feminine plural (poetic).", "amour, délice, orgue: masculine singular → feminine plural. Les grandes amours. Pure exam flex.", "B2"),
        Phrase("Les maths et la physique", "Maths and physics", "Hisabati na fizikia", null, "School subjects: les maths (plural!), la physique.", "les mathématiques, les sciences, l'histoire-géo. J'ai cours de maths à huit heures.", "A2"),
        Phrase("Un après-midi ensoleillé", "A sunny afternoon", "Alasiri yenye jua", null, "après-midi: both genders accepted, masculine preferred.", "Double-gender nouns: un/une après-midi, un/une interview, un/une enzyme. Pick one, stay consistent.", "B1"),
        Phrase("Des allers-retours à Kisumu", "Trips back and forth to Kisumu", "Safari za kwenda na kurudi Kisumu", null, "aller-retour: both parts agree.", "aller-retour → des allers-retours. Contrast porte-monnaie (invariable). The hyphen hides two rule-sets.", "B1"),
        Phrase("Le Kenya et sa savane", "Kenya and its savannah", "Kenya na nyika zake", null, "Countries: le Kenya (m), la Tanzanie (f).", "Country gender: -e ending usually feminine (la France, l'Ouganda m! exception). le Kenya, le Rwanda, le Burundi — no -e, masculine.", "A2"),
        Phrase("Les vacances d'été", "Summer holidays", "Likizo za kiangazi", null, "vacances always plural.", "les vacances, les maths, les toilettes: plural-only nouns. Always les, never le.", "A2"),
        Phrase("Un arc-en-ciel", "A rainbow", "Upinde wa mvua", null, "Hyphenated, invariable-ish.", "arc-en-ciel → des arcs-en-ciel (only arc changes). Compound logic: what can pluralize, does.", "B1"),
        Phrase("La plupart ont voté", "Most voted", "Wengi walipiga kura", null, "la plupart + PLURAL verb.", "Rare plural-collective. la plupart sont venus. Examiners test it yearly.", "B1"),
        Phrase("Un tête-à-tête", "A private chat", "Mazungumzo ya faragha", null, "tête-à-tête invariable.", "Compound adverbs-as-nouns stay fixed. Des tête-à-tête (no change). Dinner diplomacy word.", "B1"),
        Phrase("Des allers-retours", "Round trips", "Safari za kwenda na kurudi", null, "Both parts agree here.", "aller-retour → allers-retours. Contrast porte-monnaie (fixed). Check the verb inside.", "B1")
    ), "u7"),
    Lesson("g-adverbes", "💨", "Adverbes", "Adverbs: formation & position", "Vielezi", listOf(
        Phrase("Elle parle doucement", "She speaks softly", "Anaongea polepole", "Anaongea slow", "-ment = -ly. Feminine stem + ment.", "douce → doucement, lente → lentement, heureuse → heureusement. -é endings: modéré → modérément.", "A2", true),
        Phrase("Il conduit prudemment", "He drives carefully", "Anaendesha kwa uangalifu", null, "-ent → -emment, -ant → -amment.", "prudent → prudemment, constant → constamment, patient → patiemment. Double-m is the signature.", "B1"),
        Phrase("Venez vite !", "Come quickly!", "Njoni haraka!", "Njoni haraka!", "Short adverbs: vite, bien, mal, fort — no -ment.", "Irregular adverbs: bien, mal, mieux, vite. Vite never takes -ment. Viens vite, mange bien.", "A1"),
        Phrase("J'ai bien mangé", "I ate well", "Nimeshiba vizuri", "Nimeshiba fiti", "bien/mal go AFTER the participle.", "Short adverbs slot between auxiliary and participle: J'ai bien dormi. Long -ment adverbs go after: J'ai dormi profondément.", "A2"),
        Phrase("Il parle couramment français", "He speaks French fluently", "Anaongea Kifaransa fasaha", null, "-amment/-emment family again.", "courant → couramment, fréquent → fréquemment. Fluency goal-phrase for the oral exam.", "B1"),
        Phrase("Elle chante mieux que moi", "She sings better than me", "Anaimba kuliko mimi", null, "mieux = better (actions). meilleur = better (things).", "mieux + verb, meilleur + noun: Elle chante mieux. C'est la meilleure chanteuse. One letter, two categories.", "B1"),
        Phrase("C'est le plus vite possible", "It's as fast as possible", "Ni haraka iwezekanavyo", null, "le plus + adverb = superlative of manner.", "le plus vite, le mieux, le moins cher. Invariable le — never la, even for feminine subjects.", "B1"),
        Phrase("Presque tous les jours", "Almost every day", "Karibu kila siku", "Karibu daily", "presque, très, trop: pre-adverb intensifiers.", "presque fini, très bien, trop cher. They modify adjectives AND adverbs, never nouns.", "A2"),
        Phrase("Heureusement, il a plu", "Luckily, it rained", "Kwa bahati nzuri, mvua ilinyesha", null, "Sentence adverbs open with a comma.", "heureusement, franchement, évidemment frame the whole sentence. Rédaction polish: Malheureusement, rien n'a changé.", "B1"),
        Phrase("Marche lentement mais sûrement", "Walk slowly but surely", "Tembea polepole lakini kwa uhakika", "Tembea slow lakini sure", "Paired adverbs: rhythm + wisdom.", "lentement mais sûrement — proverb energy. Adverbs of manner answer 'comment ?': Comment ? — Doucement.", "A2"),
        Phrase("Tout doucement, on avance", "Very gently, we move forward", "Polepole tunasonga", "Polepole tunasonga", "tout + adverb = very (intensifier).", "tout doucement, tout près, toute seule. tout agrees before feminine adjectives starting with consonants: toute petite.", "B1"),
        Phrase("Il parle trop vite", "He speaks too fast", "Anaongea haraka sana", null, "trop + adverb/adjective.", "trop cher, trop tard, trop vite. Excess marker — complaints and warnings.", "A2"),
        Phrase("Marche droit devant toi", "Walk straight ahead", "Tembea moja kwa moja", null, "droit as adverb (invariable).", "Adjective-or-adverb twins: droit/droit, fort/fort, cher/cher. Il parle fort. Ça coûte cher.", "B1"),
        Phrase("Elle est entièrement d'accord", "She fully agrees", "Anakubali kabisa", null, "-ment from -e adjectives.", "entière → entièrement, énorme → énormément. Feminine stem + ment, always.", "B1"),
        Phrase("Longtemps après", "Long afterwards", "Muda mrefu baadaye", null, "longtemps: time adverb.", "longtemps, souvent, toujours, déjà: frequency/time shelf. Position: after verb.", "A2"),
        Phrase("Assieds-toi correctement", "Sit properly", "Keti vizuri", "Keti poa", "-ment manner + reflexive order.", "Assieds-toi bien/droit/correctement. Orders carry manner adverbs naturally.", "A2")
    ), "u7"),
    Lesson("g-prepositions", "📍", "Prépositions", "à, de, en & place/time", "Vihusiano", listOf(
        Phrase("Je vais à l'école", "I'm going to school", "Ninaenda shule", "Naenda shule", "aller À + place. Motion owns à.", "aller à, arriver à, assister à. à = direction/destination. Je vais à Mombasa, à la gare, au marché.", "A1", true),
        Phrase("Je viens de l'école", "I'm coming from school", "Ninatoka shule", "Nimetoka shule", "venir DE + place. Origin owns de.", "venir de, partir de, sortir de. de = origin. Je viens de Kisumu, du Kenya, de chez moi.", "A1"),
        Phrase("En 2026, je finis le lycée", "In 2026 I finish high school", "2026 nitamaliza sekondari", null, "Years and seasons (except spring): en.", "en 2026, en été, en hiver, en automne — BUT au printemps. Months: en mai. Days: le lundi.", "A2"),
        Phrase("Je voyage en bus", "I travel by bus", "Ninasafiri kwa basi", "Nasafiri na bus", "en + vehicle (no article). à pied on foot.", "en bus, en matatu, en avion — but à pied, à vélo, à moto, à cheval. The vehicle list is closed; memorize it.", "A2"),
        Phrase("Un cadeau pour ma sœur", "A gift for my sister", "Zawadi kwa dada yangu", null, "pour = for/purpose. par = by/means.", "pour ma sœur (recipient) vs par la fenêtre (through) vs par accident (by). Three prepositions, three jobs.", "A2"),
        Phrase("Je parle de mon village", "I talk about my village", "Ninaongea kuhusu kijiji changu", null, "parler DE. Each verb owns one preposition.", "Core pairs: parler de, penser à, rêver de, avoir besoin de, se souvenir de, s'occuper de, décider de.", "B1"),
        Phrase("Pense à ton avenir", "Think about your future", "Fikiria mustakabali wako", null, "penser À (not de!). The famous exception.", "penser à + person/thing (have in mind) vs penser de (opinion: Que penses-tu de…?). Tested pair.", "B1"),
        Phrase("Chez ma grand-mère", "At my grandma's", "Kwa bibi yangu", "Kwa shosho", "chez = at someone's place/person.", "chez moi/toi/lui, chez le médecin, chez Wanjiku. No article, no fuss — chez eats prepositions.", "A2"),
